"use strict";
import PoolAndGaugeAddress from "components/PoolAndGaugeAddress";
import { MouseoverTooltip, TooltipSize } from "components/Tooltip";
import { Flex, Text, styled as uiStyled, useSporeColors } from "ui/src";
import { InfoCircleFilled } from "ui/src/components/icons";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { NumberType, useFormatter } from "utils/formatNumbers";
const ItemWrapper = uiStyled(Flex, {
  borderWidth: 1,
  borderColor: "$surface2",
  borderRadius: "$spacing12",
  flexDirection: "column",
  gap: "$gap4",
  width: "100%",
  padding: "$spacing12"
});
const HeaderRow = uiStyled(Flex, {
  flexDirection: "row",
  alignItems: "center",
  gap: "$gap12",
  marginBottom: "$spacing12"
});
const HeadingText = uiStyled(Text, {
  variant: "heading1",
  color: "$neutral1",
  $lg: {
    variant: "heading2"
  },
  $md: {
    variant: "heading3"
  }
});
const SparkBadge = uiStyled(Flex, {
  flexDirection: "row",
  alignItems: "center",
  gap: "$gap4"
  // No specific background in screenshot for the text itself, just icon + text
});
const Badge = ({ icon, text }) => <Flex flexDirection="row" alignItems="center" gap="$gap4">
    {icon}
    <Text variant="body2" color="$neutral2">
      {text}
    </Text>
  </Flex>;
const StatsGrid = uiStyled(Flex, {
  marginTop: "$spacing24",
  "$platform-web": {
    display: "grid",
    gridTemplateColumns: "repeat(4, 1fr)",
    gap: "$gap12"
  },
  $xxl: {
    gridTemplateColumns: "repeat(2, 1fr)"
  },
  $lg: {
    gridTemplateColumns: "repeat(1, 1fr)"
  }
});
const LabelText = uiStyled(Text, {
  variant: "body2",
  color: "$neutral2",
  marginBottom: "$spacing8"
});
const SubValueText = uiStyled(Text, {
  variant: "body4",
  color: "$neutral2",
  marginTop: "$spacing4"
});
const ValueText = uiStyled(Text, {
  variant: "heading3",
  color: "$neutral1"
});
const StatItem = ({
  label,
  value,
  subValue,
  icon
}) => <ItemWrapper>
    <LabelText>{label}</LabelText>
    <Flex flexDirection="row" alignItems="center" gap="$gap4">
      <ValueText>{value}</ValueText>
      {icon}
    </Flex>
    {subValue && <SubValueText>{subValue}</SubValueText>}
  </ItemWrapper>;
export default function MarketHeader({ marketData }) {
  const { formatFiatPrice, formatNumber } = useFormatter();
  const chainId = UniverseChainId.Mainnet;
  const colors = useSporeColors();
  const totalSupplyAmount = Number(marketData.totalSupplyAssetsFormatted);
  const liquidityAmount = Number(marketData.availableLiquidityFormatted);
  const totalSupplyUsd = marketData.totalSupplyUsd;
  const liquidityUsd = marketData.availableLiquidityUsd;
  return <Flex my={"$spacing12"}>
      {
    /* Title Section */
  }

      <HeaderRow>
        <HeadingText>{marketData.collateralToken.symbol}</HeadingText>
        <HeadingText color={"$neutral2"}>/ {marketData.loanToken.symbol}</HeadingText>
        <MouseoverTooltip
    text={<PoolAndGaugeAddress poolAddress={"0x0000...0000"} gaugeAddress={"0x0000...0000"} />}
    size={TooltipSize.Max}
    placement="top"
  >
          <Flex cursor="pointer">
            <InfoCircleFilled size={28} color={colors.neutral2.val} />
          </Flex>
        </MouseoverTooltip>
      </HeaderRow>

      {
    /* Badges */
  }
      <Flex flexDirection="row" gap="$gap16" marginBottom="$spacing24">
        <Badge
    icon={<PortfolioLogo
      chainId={chainId}
      tokenSymbol={marketData.collateralToken.symbol}
      tokenName={marketData.collateralToken.name}
      images={[getTokenLogoUrl(marketData.collateralToken.address)]}
      size={18}
    />}
    text={marketData.collateralToken.symbol}
  />
        <Badge
    icon={<PortfolioLogo
      chainId={chainId}
      tokenSymbol={marketData.loanToken.symbol}
      tokenName={marketData.loanToken.name}
      images={[getTokenLogoUrl(marketData.loanToken.address)]}
      size={18}
    />}
    text={marketData.loanToken.symbol}
  />
        <Badge text={`${marketData.lltvPercent}% LLTV`} />
      </Flex>

      {
    /* Description */
  }
      <Text
    $md={{ variant: "body3" }}
    variant="body2"
    color="$neutral2"
    style={{ lineHeight: "20px", maxWidth: "800px" }}
  >
        {marketData.description}
      </Text>

      {
    /* Stats Grid */
  }
      <StatsGrid>
        <StatItem
    label="Total Market Size"
    value={formatFiatPrice({ price: totalSupplyUsd, type: NumberType.FiatTokenStats })}
    subValue={`${formatNumber({ input: totalSupplyAmount, type: NumberType.TokenTwoDecimals })} ${marketData.loanToken.symbol}`}
  />
        <StatItem
    label="Total Liquidity"
    value={formatFiatPrice({ price: liquidityUsd, type: NumberType.FiatTokenStats })}
    subValue={`${formatNumber({ input: liquidityAmount, type: NumberType.TokenTwoDecimals })} ${marketData.loanToken.symbol}`}
  />
        <StatItem label="Borrow Rate" value={`${marketData.borrowRate.toFixed(2)}%`} />
        <StatItem label="Utilization" value={`${marketData.utilizationRate.toFixed(1)}%`} />
      </StatsGrid>
    </Flex>;
}
