"use strict";
import { createContext, useContext, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { useAccount } from "wagmi";
import { useMorphoMarket, useMorphoUserBorrowPosition } from "hooks/morpho";
import { UniverseChainId } from "uniswap/src/features/chains/types";
export const MarketContext = createContext(null);
export const MarketContextProvider = ({ children }) => {
  const [activeTab, setActiveTab] = useState("Your position");
  const [searchParams] = useSearchParams();
  const { address: userAddress } = useAccount();
  const chainId = UniverseChainId.Mainnet;
  const marketId = searchParams.get("id");
  const { data: marketData, isLoading: isLoadingMarket } = useMorphoMarket(marketId ?? void 0, chainId);
  const { data: rawUserPosition, isLoading: isLoadingPosition } = useMorphoUserBorrowPosition(
    marketId ?? void 0,
    userAddress,
    chainId
  );
  const userPosition = rawUserPosition && marketData ? {
    collateral: rawUserPosition.collateral,
    collateralFormatted: rawUserPosition.collateralFormatted,
    collateralUsd: Number(rawUserPosition.collateralFormatted) * marketData.collateralPriceUsd,
    borrowShares: rawUserPosition.borrowShares,
    borrowAssets: rawUserPosition.borrowAssets,
    borrowAssetsFormatted: rawUserPosition.borrowAssetsFormatted,
    borrowAssetsUsd: Number(rawUserPosition.borrowAssetsFormatted) * marketData.loanPriceUsd,
    ltv: rawUserPosition.ltv,
    lltvPercent: rawUserPosition.lltvPercent,
    healthFactor: rawUserPosition.healthFactor,
    liquidationPrice: rawUserPosition.liquidationPrice,
    walletCollateralBalance: rawUserPosition.walletCollateralBalance,
    walletCollateralBalanceFormatted: rawUserPosition.walletCollateralBalanceFormatted,
    walletLoanBalance: rawUserPosition.walletLoanBalance,
    walletLoanBalanceFormatted: rawUserPosition.walletLoanBalanceFormatted
  } : null;
  return <MarketContext.Provider
    value={{
      activeTab,
      setActiveTab,
      marketData: marketData ?? null,
      userPosition,
      isLoadingMarket,
      isLoadingPosition,
      marketId,
      chainId
    }}
  >
      {children}
    </MarketContext.Provider>;
};
export const useMarketContext = () => {
  const context = useContext(MarketContext);
  if (!context) {
    throw new Error("useMarketContext must be used within a MarketContextProvider");
  }
  return context;
};
export const VaultContextProvider = MarketContextProvider;
export const useVaultContext = useMarketContext;
export const VaultContext = MarketContext;
