export default function LiquidationsTable() {
  const { marketId, chainId } = useMarketContext();
  const { data: liquidations, isLoading } = useMorphoMarketLiquidations(marketId ?? void 0, chainId);
  const formattedData = useMemo(() => {
    if (!liquidations) return [];
    return liquidations.map((liq) => {
      const amountUsd = parseFloat(liq.amountUSD || "0");
      const profitUsd = parseFloat(liq.profitUSD || "0");
      return {
        id: liq.id,
        dateTime: new Date(Number(liq.timestamp) * 1e3).toLocaleString(),
        liquidatedWallet: `${liq.liquidatee.id.slice(0, 6)}...${liq.liquidatee.id.slice(-4)}`,
        liquidatedWalletColor: generateWalletColor(liq.liquidatee.id),
        collateralSeized: parseFloat(liq.amount).toLocaleString(void 0, { maximumFractionDigits: 4 }),
        collateralSeizedUsd: `$${amountUsd.toLocaleString(void 0, { maximumFractionDigits: 2 })}`,
        loanRepaid: profitUsd > 0 ? `+$${profitUsd.toFixed(2)}` : "$0.00",
        loanRepaidUsd: `$${profitUsd.toLocaleString(void 0, { maximumFractionDigits: 2 })}`,
        liquidator: `${liq.liquidator.id.slice(0, 6)}...${liq.liquidator.id.slice(-4)}`,
        liquidatorColor: generateWalletColor(liq.liquidator.id)
      };
    });
  }, [liquidations]);
  return <TableWrapper>
      <LiquidationsTableComponent data={formattedData} loading={isLoading} />
    </TableWrapper>;
}
